import 'dart:convert';

import 'package:authentication/backup/kdbx_decrypt.dart';
import 'package:authentication/backup/kdbx_import.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('opens independent KDBX sample', () async {
    const encoded =
        '';
    final data = base64Decode(encoded);
    expect(
      parseKdbxPayload(await decryptKdbx(data, 'test')).accounts.length,
      7,
    );
    await expectLater(decryptKdbx(data, 'wrong'), throwsFormatException);
  });
}
